content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --radius: 12px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -1px rgba(0, 0, 0, 0.2);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 16px;
}

.dashboard-header h1 {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
}

.filter-buttons {
  display: flex;
  gap: 8px;
  background: var(--card-bg);
  padding: 4px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.btn {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  color: var(--text-main);
  background: var(--bg-color);
}

.btn.active {
  background: var(--primary-color);
  color: #ffffff;
  box-shadow: var(--shadow-sm);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.metric-card {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.metric-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.card-value .unit {
  font-size: 14px;
  font-weight: 400;
  color: var(--text-muted);
}

.card-trend {
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 2px 8px;
  border-radius: 20px;
}

.card-trend.positive {
  color: var(--success-color);
  background: rgba(16, 185, 129, 0.1);
}

.card-trend.negative {
  color: var(--danger-color);
  background: rgba(239, 68, 68, 0.1);
}

.chart-section {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.chart-section h2 {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 20px;
  color: var(--text-main);
}

.chart-container {
  width: 100%;
  height: 350px;
}

@media (max-width: 768px) {
  .app-container {
    padding: 16px;
  }

  .dashboard-header {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-buttons {
    justify-content: stretch;
  }

  .filter-buttons .btn {
    flex: 1;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
  }

  .dashboard-header h1 {
    font-size: 20px;
  }

  .metric-card {
    padding: 16px;
  }

  .card-value {
    font-size: 24px;
  }

  .chart-section {
    padding: 16px;
  }

  .chart-container {
    height: 260px;
  }
}

/**
 * 月ごとの売上データを表すインターフェース
 */
export interface SalesRecord {
  /** 月（例: '1月'） */
  month: string;
  /** 売上金額（円） */
  sales: number;
  /** 客数（人） */
  customers: number;
  /** 平均単価（円） */
  averagePrice: number;
}

/**
 * メトリックカードコンポーネントのプロパティ
 */
export interface MetricCardProps {
  /** カードのタイトル */
  title: string;
  /** 表示する数値 */
  value: string;
  /** 単位 */
  unit: string;
  /** トレンド文字列 */
  trend: string;
  /** ポジティブなトレンドかどうか */
  isPositive: boolean;
}

/**
 * 売上チャートコンポーネントのプロパティ
 */
export interface SalesChartProps {
  /** グラフに表示するデータ配列 */
  data: SalesRecord[];
}

/**
 * ダッシュボードの期間フィルターの型
 */
export type FilterType = 'all' | 'firstHalf' | 'secondHalf';

import { MetricCardProps } from '../types';

export default function MetricCard({
  title,
  value,
  unit,
  trend,
  isPositive,
}: MetricCardProps) {
  const trendClass = isPositive ? 'card-trend positive' : 'card-trend negative';
  const ariaLabel = `${title}: ${value}${unit}, トレンド ${trend}`;

  return (
    <div className="metric-card" role="region" aria-label={ariaLabel}>
      <span className="card-title">{title}</span>
      <div className="card-value">
        {value}
        <span className="unit">{unit}</span>
      </div>
      <span className={trendClass} aria-hidden="true">{trend}</span>
    </div>
  );
}

import { SalesChartProps } from '../types';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend,
  TooltipProps,
} from 'recharts';

interface CustomTooltipProps extends TooltipProps<number, string> {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    dataKey: string;
    color: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div style={{ background: '#fff', padding: '10px', border: '1px solid #e2e8f0', borderRadius: '8px', boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)' }}>
        <p style={{ fontWeight: '600', marginBottom: '5px', color: '#1e293b' }}>{label}</p>
        {payload.map((entry, index) => (
          <p key={`item-${index}`} style={{ color: entry.color, fontSize: '14px' }}>
            {entry.name}: {entry.value.toLocaleString()} {entry.dataKey === 'sales' ? '円' : '人'}
          </p>
        ))}
      </div>
    );
  }
  return null;
};

export default function SalesChart({ data = [] }: SalesChartProps) {
  if (!data || data.length === 0) {
    return (
      <div className="chart-section">
        <h2>月次推移グラフ</h2>
        <div className="chart-container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)' }}>
          データがありません
        </div>
      </div>
    );
  }

  return (
    <div className="chart-section">
      <h2>月次推移グラフ</h2>
      <div className="chart-container">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" />
            <YAxis stroke="#64748b" />
            <Tooltip content={<CustomTooltip />} />
            <Legend />
            <Line
              type="monotone"
              dataKey="sales"
              name="売上 (円)"
              stroke="#3b82f6"
              strokeWidth={2}
              activeDot={{ r: 8 }}
            />
            <Line
              type="monotone"
              dataKey="customers"
              name="客数 (人)"
              stroke="#10b981"
              strokeWidth={2}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useDashboardData } from './hooks/useDashboardData';
import MetricCard from './components/MetricCard';
import SalesChart from './components/SalesChart';

export default function App() {
  const {
    filter,
    setFilter,
    filteredData,
    totalSales,
    totalCustomers,
    avgPrice,
  } = useDashboardData();

  return (
    <div className="app-container">
      <header className="dashboard-header">
        <h1>売上ダッシュボード</h1>
        <div className="filter-buttons">
          <button
            className={`btn ${filter === 'all' ? 'active' : ''}`}
            onClick={() => setFilter('all')}
          >
            年間通算
          </button>
          <button
            className={`btn ${filter === 'firstHalf' ? 'active' : ''}`}
            onClick={() => setFilter('firstHalf')}
          >
            上半期
          </button>
          <button
            className={`btn ${filter === 'secondHalf' ? 'active' : ''}`}
            onClick={() => setFilter('secondHalf')}
          >
            下半期
          </button>
        </div>
      </header>

      <div className="metrics-grid">
        <MetricCard
          title="総売上"
          value={totalSales.toLocaleString()}
          unit="円"
          trend="+12.5% 前年比"
          isPositive={true}
        />
        <MetricCard
          title="総客数"
          value={totalCustomers.toLocaleString()}
          unit="人"
          trend="+8.2% 前年比"
          isPositive={true}
        />
        <MetricCard
          title="平均単価"
          value={avgPrice.toLocaleString()}
          unit="円"
          trend="-1.1% 前年比"
          isPositive={false}
        />
      </div>

      <SalesChart data={filteredData} />
    </div>
  );
}

import { useState, useMemo } from 'react';
import { FilterType } from '../types';
import { sampleData } from '../constants';

export function useDashboardData() {
  const [filter, setFilter] = useState<FilterType>('all');

  const filteredData = useMemo(() => {
    if (filter === 'firstHalf') return sampleData.slice(0, 6);
    if (filter === 'secondHalf') return sampleData.slice(6, 12);
    return sampleData;
  }, [filter]);

  const totalSales = useMemo(() => {
    return filteredData.reduce((acc, cur) => acc + cur.sales, 0);
  }, [filteredData]);

  const totalCustomers = useMemo(() => {
    return filteredData.reduce((acc, cur) => acc + cur.customers, 0);
  }, [filteredData]);

  const avgPrice = useMemo(() => {
    return filteredData.length > 0
      ? Math.round(filteredData.reduce((acc, cur) => acc + cur.averagePrice, 0) / filteredData.length)
      : 0;
  }, [filteredData]);

  return {
    filter,
    setFilter,
    filteredData,
    totalSales,
    totalCustomers,
    avgPrice,
  };
}
